contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function driving the test
    function run(uint newMin) public payable {
        // read contract balance before
        uint balBefore = address(c).balance;
        // read MinSum before
        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        // attempt to call SetMinSum; it may revert if intitalized is true
        bool reverted;
        c.SetMinSum(newMin); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read MinSum and contract balance after
        uint minAfter = c.MinSum(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // If the call did not revert, then MinSum must equal newMin and contract balance must be unchanged.
        // If it reverted, MinSum must be unchanged from before or equal to newMin only if revert semantics allowed (we require only the non-revert case here).
        assert(reverted || (minAfter == newMin && balAfter == balBefore));
    }

    // receive to allow funding if needed by the harness (not used here)
    receive() external payable {}
}

