pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 newMin) internal {
        uint balBefore = address(c).balance;
        uint256 minBefore;
        try c.MinSum() returns (uint256 __r) { minBefore = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(newMin) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 minAfter;
        try c.MinSum() returns (uint256 __r) { minAfter = __r; } catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(reverted || (minAfter == newMin && balAfter == balBefore));
    }

    function testFuzz_run(uint256 newMin) public {
        _run(newMin);
    }

    receive() external payable {}
}
